"""Compare final native/Web observations with immutable 0.4.0 expectations."""
import copy,gzip,hashlib,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2];E=ROOT/'validation/performance-0.4.1'
def read(path):
 if not path.exists():path=path.with_suffix(path.suffix+'.gz')
 raw=path.read_bytes();return json.loads(gzip.decompress(raw) if path.suffix=='.gz' else raw)
def norm(v,identity=True):
 v=copy.deepcopy(v);v['metrics'].pop('generation_seconds',None)
 if identity:
  v.pop('request_fingerprint');v['diagnostics'].pop('implementation',None)
  if v['map']:
   v['map'].pop('map_id');v['map']['generator'].pop('implementation');v['map']['generator'].pop('request_fingerprint')
 return v
old=read(E/'baseline/native-matched.json');new=read(E/'final/native.json');webold=read(E/'baseline/web/summary.json');webnew=read(E/'final/web/summary.json');webraw=read(E/'final/web/report.json.gz');replay=read(E/'final/replay/summary.json');checks={}
for folder in ['checks-first','checks']:
 for c in read(E/'final'/folder/'checks.json')['checks']:checks[c['check']]=dict(c,evidence='final/'+folder+'/'+c['check']+'.log')
assert all(c['status']=='PASS' for c in checks.values()),checks
pairs=[];verifications={}
for label,a,b in [('native',old,new),('threaded_web',webold,webnew)]:
 for before,after in zip(a['records'],b['records']):
  assert before['stage']==after['stage'] and before['seed']==after['seed']
  pairs.append(dict(runtime=label,stage=after['stage'],seed=after['seed'],old={k:v for k,v in before.items() if k!='result'},new={k:v for k,v in after.items() if k!='result'},active_reduction=1-after['advance_cpu_usec']/before['advance_cpu_usec'],wall_reduction=1-after['wall_usec']/before['wall_usec']))
for a,b,c in zip(old['records'][1:],new['records'][1:],webraw['records'][1:]):
 seed=str(b['seed']);verifications[seed]={'full_old_new_projection':norm(a['result'])==norm(b['result']),'full_native_web_except_time':norm(b['result'],False)==norm(c['result'],False),'old_fingerprint':a['result']['request_fingerprint'],'new_fingerprint':b['result']['request_fingerprint'],'expansions':b['result']['metrics']['expansions']}
oldfailure=read(ROOT/'validation/runtime-reward-B/replay/failure.json.gz')['result'];failure=read(E/'final/web-failure/report.json.gz')['records'][-1]['result'];verifications['real_failure']={'status':failure['status'],'empty_map':failure['map'] is None and failure['content_store']=={},'full_old_new_projection':norm(oldfailure)==norm(failure)}
fresh=read(E/'final/web-fresh2/report.json.gz')['records'][-1]['result'];verifications['second_fresh']={'full_first_second_except_time':norm(fresh,False)==norm(webraw['records'][1]['result'],False)}
cancel=[]
for folder in ['web-cancel-preload','web-cancel-prepare','web-cancel-generate']:
 r=read(E/'final'/folder/'report.json.gz')['records'][-1];v=r.get('result');intent=r['cancel'];assert intent['trusted']
 cancel.append(dict(evidence='final/'+folder,stage=r['stage'],result_status=v['status'] if v else r['status'],phase=v['diagnostics']['error']['phase'] if v else 'derived_json',empty_map=(v['map'] is None and v['content_store']=={}) if v else None,expanded=v['metrics'].get('expansions') if v else None,input_to_done_ms=intent['input_to_done_ms'],event_queue_ms=intent['handler_ms']-intent['intent_ms'],handler_to_observed_ms=intent['observed_ms']-intent['handler_ms'],sdk_cancel_ms=intent['finished_ms']-intent['observed_ms']))
assert replay['status']=='PASS' and all(v.get('full_old_new_projection',True) and v.get('full_native_web_except_time',True) and v.get('full_first_second_except_time',True) for v in verifications.values())
assert all(c['result_status']=='CANCELLED' and c['empty_map'] is not False for c in cancel)
source={p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in (ROOT/'godot_runtime/addons/mapgen').glob('*.gd')};assert source==replay['source_sha256']
report=dict(status='PASS',algorithm='stable-v3-reward-space',implementation='mapgen/gdscript-candidate-0.4.1',readiness='candidate',pairs=pairs,checks=list(checks.values()),behavior=verifications,replay_cases=47,original_40_seeds='40 complete results equal except declared identity/time',cancel=cancel,cache_rebuild=read(E/'final/cache_rebuild.json'),tested_source_sha256=source,web_warm=read(E/'final/web-warm/summary.json'),web_fresh2=read(E/'final/web-fresh2/summary.json'),toolchain=read(ROOT/'performance_revision/upstream/reproduction.json'),measurement='wall inside advance, including bookkeeping; active CPU proxy, not OS thread CPU; remainder includes yielding, rendering and harness',not_verified=['actual gunman-rush PCK/SceneTree/Provider/Motor','original main-game double-fresh 300-second tool/image itinerary','mobile, hard frame bound, whole-map physics','candidate nonthreaded Web export this round'])
(E/'report.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n')
def sec(us):return f'{us/1e6:.3f}'
lines=['# 0.4.1 性能与一致性报告','','原件：0.4.0 / stable-v3-reward-space；新实现：mapgen/gdscript-candidate-0.4.1。输入、90 秒搜索配置、500000 候选上限、seed、目标和模块内容不变。本表是本机单次对照，附第二个独立 fresh 复验，不是统计性能保证。机器原始结果、阶段分布、取消事件及全部来源在 validation/performance-0.4.1/；包内有汇总 evidence/report.json。','','## 同输入旧新实测','','Godot 4.7.2.stable.custom_build.gunman_sd1.ed1daf0bf，二进制 SHA eeaec2b65dc3234168be1e1cbcc89731514bbb78dfb2c1b502920c50830a0638。Web 使用下游锁定的 threaded release 模板、Compatibility、COOP/COEP、软件 Chromium。两个版本都由单主线程调用 advance(1)，每 tick 上限 128、软 8ms。active 是每次 advance 内单调钟耗时之和，包含算法和调用内记账；不含主动让帧，不是 OS 线程 CPU 计数。残差包含让帧、渲染、桥接和宿主基准脚本，不能全部归为纯算法。构造请求/Job、引擎启动和导出也不在此阶段计时中。','','| 环境 / 阶段 | 旧墙钟 s | 新墙钟 s | 旧 active s | 新 active s | 墙钟下降 |','| --- | ---: | ---: | ---: | ---: | ---: |']
for p in pairs:lines.append(f"| {p['runtime']} / {p['stage']} {p['seed'] or ''} | {sec(p['old']['wall_usec'])} | {sec(p['new']['wall_usec'])} | {sec(p['old']['advance_cpu_usec'])} | {sec(p['new']['advance_cpu_usec'])} | {p['wall_reduction']:.1%} |")
lines+=['','旧 Web 930001 残差 '+sec(webold['records'][1]['host_and_yield_usec'])+' 秒，新版 '+sec(webnew['records'][1]['host_and_yield_usec'])+' 秒。下游原 preload 27.072 秒在此复现为约 26.4 秒；下游 SDK wall 71.843 秒在这里旧版约 57.6 秒，差距尚未因果归因。未运行其 218920072 字节 PCK、宿主物理或截图/审图工具，不能用这里的独立结果签主游戏 300 秒 consumer 通过。原报告图间 20–40 秒含工具往返/审图，未计为算法 CPU。','','第二个独立浏览器 fresh 的 930001：preload '+sec(report['web_fresh2']['records'][0]['wall_usec'])+' 秒，generate '+sec(report['web_fresh2']['records'][1]['wall_usec'])+' 秒；完整结果除时间与首个 fresh 相等。同一上下文重新完整预载的冷/热墙钟为 '+', '.join(sec(x['wall_usec']) for x in report['web_warm']['records'])+' 秒，均重新核验 ZIP 和 657 文件。热预载没有跳过校验；复用已验证 library 则可直接创建下一 job，主测试的 930007 使用同一 library。','','## 热点与实际改动','','原生诊断包装器的 self time（有额外计时开销，不能当发布性能）显示：930001 graph 3.366s、reachable 1.769s、growth_options 1.940s；配置检查 127538 次。原预载的 module_json 约 2.19s、catalog_json 约 1.07s，ZIP entry 约 0.48s，文件 SHA 约 0.06s；JSON 是主要优化对象。诊断中间版本配置调用降到 74289 次；原图/可达调用数仍为 3297/7761。完整诊断和未采用的较慢试验也保留。','','- 使用绑定模块 SHA/实现的可重建源 JSON 派生缓存；保留整数类型和 binary64 位。缓存缺失/不匹配走原解析路径，篡改 ZIP 仍拒绝。每次读取完整 ZIP、解压原文件、验证整包 SHA 与全部 657 个成员；没有减内容或改成预存地图查询。','- 候选仍先执行原 candidate tick；相同整数严格矩形相交测试提前到纯 make() 分配之前，省去必被拒绝候选的 Port/镜像对象创建。','- job 内复用模块局部路线图、以不可变数组替代 JSON 状态键、用完整结构比较的图驻留池和引用身份复用可达性结果。缓存不共享求解可变状态，不消耗 RNG。','- 稳定排序显式以原始索引打破相同评分；比较器纯计算。可达性每八个节点检查取消，减少解释器协程开销。一个操作仍为 16 检查点，但总操作数会下降。','- progress 直接构造相同字段，减少每次推进的临时 Dictionary。最终审计/导出内容和结果快照合同保留。','','新原生 930001 阶段 active（按 advance 入口归属，跨界调用计在入口）为：']
lines += ['  '+', '.join(k+'='+sec(v['total_usec'])+'s' for k,v in new['records'][1]['profile']['phases'].items())+'.','', 'Web 单次推进分布（毫秒；原始 report 另有每阶段 p50/p95/p99/最大及 tick 分布）：','','| 阶段 | p50 | p95 | p99 | 最大 | tick 最大 |','| --- | ---: | ---: | ---: | ---: | ---: |']
for r in webnew['records']:
 d=r['advance_distribution_usec'];lines.append('| '+r['stage']+' '+str(r['seed'] or '')+' | '+' | '.join(f'{d[k]/1000:.3f}' for k in ['p50','p95','p99','max'])+f" | {r['tick_max_usec']/1000:.3f} |")
lines+=['','最大长步仍超过 8/16ms；原生首次加载缓存脚本约 75ms（跨阶段计在 zip_entries），Web 新最大推进约 32ms。原版 Web 最大推进约 23–28ms，因此总耗时改善不能宣称尾延迟改善。缓存加载、ZIP 单成员解压、原生排序和完整结果深拷贝仍有原子工作；没有硬帧/手机时延保证。软 8ms 只是单位完成后的让出目标。','','## 快照、序列化及宿主边界','','| 环境/seed | result() ms | 宿主再次 duplicate ms | canonical 序列化 ms | 引擎 JSON ms |','| --- | ---: | ---: | ---: | ---: |']
for label,d in [('native',new),('web',webnew)]:
 for r in d['records'][1:]:lines.append(f"| {label}/{r['seed']} | "+' | '.join(f'{r[k]/1000:.3f}' for k in ['snapshot_usec','host_duplicate_usec','canonical_serialize_usec','engine_serialize_usec'])+' |')
lines+=['','固定宿主 runtime_map_generation_job.gd:295 使用 job.result().duplicate(true)，:332 再次复制 actual 后进入 Provider；:249/:289 每 tick 记录 progress。完整调用位置、原 blob 和 URL 见 upstream/host_calls.json。这些确实存在，但本次几毫秒的独立复制计时、下游原 validate 137.161ms 不能解释全部 72 秒生成。额外约 14 秒的宿主差距没有同场 CPU 栈证据，本轮不归责宿主具体函数。后续需在同一次下游运行记录 SDK phase/call total、frame/tick wall 和完整包时钟，沿已有 begin→preload→generate→validate→assemble→physics→commit 归属，而不是扩大 90 秒限额。','','## 真实输入到取消完成','','| 场景 | 输入→完成 ms | 事件队列 ms | handler→宿主观察 ms | cancel 内 ms |','| --- | ---: | ---: | ---: | ---: |']
for c in cancel:lines.append('| '+c['phase']+' | '+' | '.join(f'{c[k]:.3f}' for k in ['input_to_done_ms','event_queue_ms','handler_to_observed_ms','sdk_cancel_ms'])+' |')
lines+=['','这些是 Playwright/CDP 发送的真实 trusted Escape 事件，使用 event.timeStamp→最终完成时 performance.now，包含队列等待；不是只计 cancel()。搜索取消时已有展开，结果 CANCELLED、map=null、content_store={}。原生另覆盖 growth/final_audit/export 和 created/prepare；并行交错 job 取消左侧后右侧 930007 仍通过且 88856 次展开。只证明这些观测，没有所有阶段/设备的最大响应保证。','','## 行为、失败及保护检查','','47 原件对照通过：40 个原 seed 全部保持完整结果、另有默认成功、真实 SEARCH_EXHAUSTED/196 失败、17/128 批次和三阶段取消。总计 43 PASS / 1 SEARCH_EXHAUSTED / 3 CANCELLED。jobs 另验证 1/17/128/4096 批次全结果相等、独立结果快照、输入快照、完成幂等及预算。取消发生位置随检查点改变可变化；取消之后不能额外推进。','','| seed | 原指纹 | 新指纹 | 展开数 |','| --- | --- | --- | ---: |']
for seed in ['930001','930007']:
 v=verifications[seed];lines.append(f"| {seed} | {v['old_fingerprint']} | {v['new_fingerprint']} | {v['expansions']} |")
lines+=['','只投影 root request_fingerprint、map_id、map.generator implementation/request_fingerprint、diagnostics implementation、metrics.generation_seconds。没有投影布局、图、内容、RNG 状态、证明、拒绝计数或候选数。Web 两 seed 还与本实现原生完整结果（仅除时间）相等；Web 真实失败与旧失败按同投影相等，无可用 map/store。','','foundation123、decimal409/seed4、hypot1005、reward_geometry13、budget5、缓存/共享库合同、jobs、Python 接口14/参考7、prototype 和旧20 seed replay 通过（原16可接受/4已知拒绝保持）。支持 seed 范围继续 [-9007199254740991,9007199254740991]，超出拒绝，不截断。缓存从锁定 ZIP 使用源 JSON 路径重建后逐字节 SHA 相等，所有源 JSON 递归检查类型/浮点位相等。','','保留首次检查失败 checks-first：Python 参考测试因漏设 MAPGEN_REFERENCE_MODULE_ZIP 未启动，补上显式锁定路径后 7 通过；旧 jobs 取消断言硬写第17次展开，但单位布局优化后首次观察为30。改为断言观察到至少17次、cancel 后展开不变且空结果，原失败日志保留。没有改旧包/旧生成预期；其他检查原通过项未重复执行。','','浏览器 console/pageerror 原日志保留。此次候选各浏览器运行没有 pageerror；这不是主游戏 audio/场景或整图可玩检查。此轮只实测 threaded Web，包里沿用的非线程示例导出 preset 未在本轮运行。','','## 下游换锁的准确边界','','固定 PR129 仅更换 JSON 锁仍会被版本准入拒绝：runtime_map_generation_job.gd:340 固定 version=0.4.0，runtime_map_v2_provider.gd:143 固定 implementation=...0.4.0、:151 固定 package.version=0.4.0；安装器也固定 archive/implementation/18 文件摘要。下游显式升级时应同步这些受锁版本值与新 manifest 的 19 文件 pin，保持原 provenance 相互校验和算法名 stable-v3-reward-space。调度循环、Provider 转换合同及地图数据结构无新增要求。本仓库只读核对，不修改主游戏；不能声称固定下游 head 已仅换锁运行了新包。','','不复用旧实现指纹、旧来源存档或旧宿主内容身份。新包 release head/source commit/ZIP SHA 按实际交付填写；原模块/输入 SHA 不变。下游应使用原 8ms/128/advance(1)、两原请求、原 90 秒及原 300 秒整段 consumer 验证，不用本仓库独立 fresh 代签。map-edit 无新增字段需求；仍 1.1.0。没有添加危险/随机布怪，没有合并或部署。']
